const i={title:"TripReel - Ilmainen Matka-animaatiosovellus: Muunna Valokuvat Kauniisiin Videoihin",description:"Luo upeita matkavideoita animoiduilla kartoilla ja lentoreiteillä. Ilmainen matka-animaatiosovellus 3D-maapallon reittikartoituksella. Muunna valokuvasi kauniisiin matkavideoihin automaattisesti. Yksityisyys ensin, toimii offline-tilassa.",keywords:"matka-animaatiosovellus, matka-kartta-animaatiosovellus, matka-reitti-animaatiosovellus, lento-animaatiosovellus, matkavideoiden tekijä, automaattinen matkavideo, animoitu matkakartta, lentoreitti-animaatio, matka-animaatio, maapallo-animaatio, matka-yhteenvetovideo, kuva videoksi, matka-kohteet, ilmainen matkavideo, offline-videotekijä, yksityinen matkavideo, kamerarullan video"},a={logoAlt:"TripReel-logo",appName:"TripReel",howItWorks:"Miten se toimii",video:"Video",features:"Ominaisuudet",theApp:"Sovellus"},t={badge:"Muuta kuvat matkakertomuksiksi",title1:"Kamerarullasi,",title2:"täydessä käytössä",description:"TripReel luo automaattisesti kauniita matkavideoita kuviesi sijaintitiedoista. Katso matkojesi heräävän eloon upeilla animoiduilla reittikartoilla ja lentoradoilla 3D-maapallolla, kun tietosi pysyvät yksityisinä ja turvassa.",secure:"100% turvallinen",worksOffline:"Toimii offline-tilassa",globeAlt:"TripReel maapallo-animaatio"},e={title:"Miten se toimii",subtitle:"Kolme yksinkertaista vaihetta täydellisen matkavideon luomiseen",step1:{title:"Salli pääsy kuviin",description:"Anna TripReelille pääsy kuvagalleriaasi. Sovellus lukee vain sijaintitiedot, ei mitään muuta."},step2:{title:"Automaattinen matkojen tunnistus",description:"TripReel analysoi sijaintitiedot ja löytää älykkäästi matkasi päivämäärien ja sijaintien perusteella."},step3:{title:"Luo videosi",description:"Katso matkasi kehittyvän kauniissa maapallo-animaatiossa, valmiina jaettavaksi sosiaalisessa mediassa."}},s={title:"Näe taikuus tapahtumassa",subtitle:"Katso miten TripReel muuttaa kuvagalleriasi hämmästyttäviksi matkavideoiksi",caption:"Näin lopullinen matkavideosi voi näyttää"},l={title:"Kaikki mitä tarvitset",subtitle:"Tehokkaita ominaisuuksia nykyaikaisille matkailijoille",twoTap:{title:"Matkavideoita kahdella napautuksella",description:"Luo upea matkavideo kuvagalleriasta vain kahdella napautuksella. Ei muokkausta tarvita."},smartTrip:{title:"Älykäs matkojen tunnistus",description:"Löytää ja ryhmittelee automaattisesti matkasi analysoimalla päivämääriä ja sijaintitietoja kuvistasi."},globe:{title:"Kaunis maapallo-animaatio",description:"Katso matkasi heräävän eloon upean 3D-maapallon kanssa, joka näyttää animoidut matkareittisi ja lentoreitit ympäri maailmaa."},privacy:{title:"Yksityisyys ensin",description:"Kaikki käsitellään laitteellasi. Kuvasi eivät koskaan poistu puhelimestasi. Toimii lentotilassa."},customStyles:{title:"Mukautetut tyylit",description:"Valitse useista maapallostyleistä ja mukautuksista sopivaksi estetiikkaasi ja tee jokaisesta videosta ainutlaatuinen."},manualControl:{title:"Manuaalinen hallinta",description:"Voit lisätä manuaalisesti kokonaan uusia matkoja, jos sijaintipalvelut eivät olleet käytössä laitteellasi."}},o={title:"Luovia video-ideoita",subtitle:"Inspiroidu siitä, mitä voit luoda TripReelillä. Nopeista viikonloppureissuista vuoden kestäviin seikkailuihin, luo upeita matkavideoita jokaisesta matkasta.",description:"Teetkö matkakartta-animaation, dokumentoit lentoreitin vai kokoat vuoden lopun matkakatsauksen, TripReel tekee muistojen muuttamisesta jaettaviksi videoiksi vaivatonta.",ideas:{yearRecap:{title:"Vuoden 2025 matkakatsaus",description:"Luo automaattisesti vuoden 2025 matkakatsausvideosi"},europeRoadTrip:{title:"Euroopan roadtrip",description:"Esittele eurooppalainen seikkailusi animoiduilla reittikartoilla"},southeastAsia:{title:"Kaakkois-Aasian matka",description:"Visualisoi reppu selässä -reittisi useiden maiden läpi"},japanRail:{title:"Japanin junamatka",description:"Luo kartavideoita junareitseistäsi Japanissa"},crossCountry:{title:"Halki USA:n",description:"Muuta amerikkalainen roadtrippisi eeppiseksi reittivideoksi"},islandHopping:{title:"Saariloikkaus",description:"Näytä saarelta saarelle -matkasi upeilla 3D-animaatioilla"},worldTour:{title:"Maailmankierros-kokoelma",description:"Useita matkoja yhdessä hämmästyttävässä maailmanlaajuisessa matkavideossa"},travelPlans:{title:"Matkasuunnitelmat 2026",description:"Visualisoi ja suunnittele jännittävät matkaseikkailusi vuodelle 2026"},lifetimeTravel:{title:"Elämän matkatarina",description:"Luo video, joka esittelee kaikki elinikäiset matkasi"},regionalExplorer:{title:"Alueellinen tutkija",description:"Kartoita seikkailusi osavaltioiden, maakuntien ja alueiden läpi"},festivalCircuit:{title:"Festivaalikierros",description:"Kartoita musiikkifestivaali- ja tapahtumamatkasi"},bikeRoutes:{title:"Kaupunkilomani",description:"Esittele kaikki kaupunkipakomatkasi"}}},n={title:"Sovellus",subtitle:"Saatavilla nyt App Storessa",alt1:"Automaattiset matkavideoit - Luo upeita videoita sekunneissa",alt2:"Kuvien sijaintitunnistus - Käyttää kuviesi metatietoja",alt3:"Matkojen tunnistus - Ryhmittelee automaattisesti matkasi",alt4:"Kauniit maapallo-videot - Maapallo-animaatio matkastasi",alt5:"Mukautetut tyylit - Personoi matkavideoitasi"},k={comingSoon:"Tulossa pian",androidTitle:"Android-sovellus tulossa pian!",androidMessage:'Android-versio ei ole vielä saatavilla, mutta tulee pian. Lähetä viesti osoitteeseen <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a>, niin ilmoitan kun se on valmis!',gotIt:"Selvä!"},u={title:"Usein kysytyt kysymykset",subtitle:"Kaikki mitä sinun tarvitsee tietää TripReelistä",q1:{question:"Voinko todella käyttää sovellusta täysin lentotilassa?",answer:"Kyllä! Premium-käyttäjät voivat käyttää sovellusta täysin offline-tilassa lentotilassa ilman rajoituksia. Ei-premium-käyttäjillä jotkin ominaisuudet ovat mainostuettuja, mikä saattaa vaatia internetin tilapäistä käyttöönottoa, mutta premium-käyttäjillä ei ole mainoksia ja sovellusta voi käyttää täysin lentotilassa."},q2:{question:"Päivitin Premiumiin, miten voin poistaa vesileiman?",answer:"Monet kysyvät mitä sovellusta käytettiin näiden videoiden luomiseen, joten premiumiin päivittämisen jälkeen sinulla on mahdollisuus lisätä pienempi versio vesileimasta (vain sovelluksen nimi) tai poistaa se kokonaan jos haluat."},q3:{question:"Ovatko kuvatietoni turvassa ja yksityisiä?",answer:"Ehdottomasti! TripReel lukee vain sijaintitiedot kuvistasi - emme koskaan käytä, tallenna tai lähetä varsinaista kuvasisältöä. Kaikki käsittely tapahtuu paikallisesti laitteellasi, eikä mikään tieto koskaan poistu puhelimestasi. Voit varmistaa tämän käyttämällä sovellusta lentotilassa - se toimii täydellisesti offline-tilassa!"},q4:{question:"Entä jos kuvissani ei ole sijaintitietoja?",answer:"Ei ongelmaa! Jos sijaintipalvelut eivät olleet käytössä kun otit kuvasi, voit manuaalisesti luoda matkoja ja lisätä sijainteja itse. Sovellus antaa sinulle täyden hallinnan mukauttaa matka-aikajanasi."},q5:{question:"Miten sovellus tunnistaa matkani automaattisesti?",answer:"TripReel analysoi sijaintitiedot ja aikaleimaukset kuvistasi tunnistaakseen älykkäästi milloin ja missä matkustit. Se ryhmittelee lähellä olevat sijainnit ja päivämäärät yhteen tunnistaakseen matkasi automaattisesti ilman manuaalista työtä."},q6:{question:"Voinko mukauttaa videoideni ulkoasua?",answer:"Kyllä! Voit valita useista maapallostyleistä ja mukauttaa erilaisia animoitujen matkavideoiden ominaisuuksia sopivaksi henkilökohtaiseen estetiikkaasi. Premium-käyttäjät saavat pääsyn lisäreittien animaatiostyyleihin, karttateemoihin ja lentoreittivaihtoehtoihin."},q7:{question:"Pitääkö minun luoda tili?",answer:"Tiliä ei tarvita! TripReel toimii heti latauksen jälkeen. Ei rekisteröitymistä, ei kirjautumista eikä henkilökohtaisia tietoja tarvita. Lataa vain sovellus ja aloita matkavideoiden luominen heti."},q8:{question:"Miksi jokin sijainti puuttuu matkastani?",answer:"Sovellus voi toimia vain saatavilla olevilla tiedoilla, joten ensinnäkin tarvitset ainakin pari kuvaa kyseisessä sijainnissa. Toiseksi sinun täytyy varmistaa, että sijaintitiedot olivat käytössä kun olit siellä. Kolmanneksi joskus heikko GPS-vastaanotto voi aiheuttaa vääriä sijaintitietoja. Jos olet sulkenut nämä kaikki pois eikä sijaintisi silti näy, voit manuaalisesti lisätä sijainnin Matkojen yleiskatsaus > Muokkaa-painikkeesta. Käytä myös Yhteystiedot raportoidaksesi ongelman."},q9:{question:"Mihin voin jakaa upean videoni?",answer:"Tietysti voit myös jakaa sen kaikilla sosiaalisen median alustoilla. Paremmin alustalle sopivaksi sovellus mahdollistaa erilaiset kuvasuhteet videoillesi."},q10:{question:"Mistä voin raportoida virheen?",answer:"Ota vain yhteyttä suoraan osoitteeseen marian@qod.ee ja selitä lyhyesti mikä ongelma on."}},m={title:"Sähköpostituki",description:"Jos sinulla on palautetta tai kohtaat ongelmia, ota rohkeasti yhteyttä suoraan tähän sähköpostiin, niin luen ja käsittelen pyyntösi henkilökohtaisesti mahdollisimman nopeasti. Kiitos sovelluksen käytöstä!",close:"Sulje"},r={default:{title:"🍪 Evästeet",message:"Käytämme evästeitä TripReel-sivustolla parantaaksemme kokemustasi. Henkilökohtaisia tietoja ei kerätä.",accept:"Hyväksy",decline:"Hylkää",details:"Tiedot"},theme:{title:"🍪 Evästeet",message:"🌙 Tallentaaksesi teemavalintasi sinun täytyy hyväksyä välttämättömät evästeet TripReel-sivustolla. Ilman niitä teemavalintaasi ei voi tallentaa.",accept:"Hyväksy",decline:"Hylkää",details:"Tiedot"}},v={privacy:"Sovelluksen tietosuojakäytäntö",cookies:"Sivuston evästekäytäntö",contact:"Yhteystiedot",cookiePreferences:"Evästevalinnat",madeWith:"Tehty",forTravelers:"matkailijoille ympäri maailmaa",copyright:"© {{year}} TripReel."},p={title:"Valmis jakamaan matkasi?",description:"Lataa TripReel tänään ja muuta kamerarullasi kauniiksi matkavideoiksi animoiduilla kartoilla ja reiteillä. Seikkailusi ansaitsevat tulla juhlistetuiksi.",features:"Ilmainen lataus • Nopea ja kätevä • Yksityisyys taattu"},d={meta:i,header:a,hero:t,howItWorks:e,videoSection:s,features:l,videoIdeas:o,screenshots:n,appStore:k,faq:u,contact:m,cookieBanner:r,footer:v,cta:p};export{k as appStore,m as contact,r as cookieBanner,p as cta,d as default,u as faq,l as features,v as footer,a as header,t as hero,e as howItWorks,i as meta,n as screenshots,o as videoIdeas,s as videoSection};
